-- 관할 구역: A-DSP-060 + 거점 범위(BR-102)
CREATE POLICY tech_zone_select ON public.technician_zone FOR SELECT TO authenticated
  USING (public.has_permission('A-DSP-060', 'READ') AND public.can_access_branch(branch_id));
--> statement-breakpoint
CREATE POLICY tech_zone_write ON public.technician_zone FOR ALL TO authenticated
  USING (public.has_permission('A-DSP-060', 'UPDATE') AND public.can_access_branch(branch_id))
  WITH CHECK (public.has_permission('A-DSP-060', 'UPDATE') AND public.can_access_branch(branch_id));
--> statement-breakpoint
